-- Broadens the "success" field to also capture failure -- renamed to
-- end_result so the column name doesn't lie once it can hold 'failed'.
-- Drops whatever check constraint currently exists on it (looked up
-- dynamically rather than by a guessed autogenerated name, since this
-- project's migration history has had drift before and the name isn't
-- guaranteed -- same reasoning as the Linear-project-mapping migration).

alter table public.tickets rename column success to end_result;

do $$
declare
  c record;
begin
  for c in
    select conname from pg_constraint
    where conrelid = 'public.tickets'::regclass
      and contype = 'c'
      and conname ilike '%success%'
  loop
    execute format('alter table public.tickets drop constraint %I', c.conname);
  end loop;
end $$;

alter table public.tickets
  add constraint tickets_end_result_check
  check (end_result in ('fully_automated', 'escalated_successfully', 'failed'));
